383	  sortSessions(sort: Sort, sessions: TestSession[]): TestSession[] {
384	    return sessions
385	      .sort((session1, session2) => {
386	        const sortDirectionFactor = (sort.direction === 'asc' ? 1 : -1);
387	        if (sort.active === 'timestamp') {
388	          return (session1.data.timestamp - session2.data.timestamp) * sortDirectionFactor;
389	        }
390	        if (sort.active === '_checked') {
391	          const session1isChecked = this.isChecked(session1);
392	          const session2isChecked = this.isChecked(session2);
393	          if (!session1isChecked && session2isChecked) {
394	            return 1 * sortDirectionFactor;
395	          }
396	          if (session1isChecked && !session2isChecked) {
397	            return -1 * sortDirectionFactor;
398	          }
399	          return 0;
400	        }
401	        if (sort.active === '_superState') {
402	          return (TestSessionsSuperStates.indexOf(session1.state) -
403	            TestSessionsSuperStates.indexOf(session2.state)) * sortDirectionFactor;
404	        }
405	        if (sort.active === '_currentBlock') {
406	          const s1curBlock = session1.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
407	          const s2curBlock = session2.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
408	          return s1curBlock.localeCompare(s2curBlock) * sortDirectionFactor;
409	        }
410	        if (sort.active === '_currentUnit') {
411	          const s1currentUnit = session1.current?.unit?.label ?? 'zzzzzzzzzz';
412	          const s2currentUnit = session2.current?.unit?.label ?? 'zzzzzzzzzz';
413	          return s1currentUnit.localeCompare(s2currentUnit) * sortDirectionFactor;
414	        }
415	        if (sort.active.startsWith('bookletState:')) {
416	          const bookletState = sort.active.replace('bookletState:', '');
417	          const label = (session: TestSession): string =>
418	            TestSessionUtil.bookletStateLabel(session, bookletState) ?? 'zzzzzzzzzz';
419	          const a = label(session1);
420	          const b = label(session2);
421	          return a.localeCompare(b) * sortDirectionFactor;
422	        }
423	        let valA = session1.data[sort.active as keyof typeof session1.data] ?? 'zzzzzzzzzz';
424	        let valB = session2.data[sort.active as keyof typeof session2.data] ?? 'zzzzzzzzzz';
425	        if (typeof valA === 'number') {
