   259	  getSessionColor(session: TestSession): string {
   260	    const stripes = (c1: string, c2: string) => `repeating-linear-gradient(45deg, ${c1}, ${c1} 10px, ${c2} 10px, ${c2} 20px)`;
   261	    const hsl = (h: number, s: number, l: number) => `hsl(${h}, ${s}%, ${l}%)`;
   262	    const colorful = this.displayOptions.highlightSpecies && session.booklet.species;
   263	    const h = colorful ? (
   264	      session.booklet.species.length *
   265	      session.booklet.species.charCodeAt(0) *
   266	      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
   267	      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
   268	      session.booklet.species.charCodeAt(session.booklet.species.length / 2) *
   269	      session.booklet.species.charCodeAt(3 * (session.booklet.species.length / 4)) *
   270	      session.booklet.species.charCodeAt(session.booklet.species.length - 1)
   271	    ) % 360 : 0;
   272	
   273	    switch (session.state) {
   274	      case 'paused':
   275	        return hsl(h, colorful ? 45 : 0, 90);
   276	      case 'pending':
   277	      case 'locked':
   278	        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 0, 92));
   279	      case 'error':
   280	        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 30, 95));
   281	      default:
   282	        return hsl(h, colorful ? 75 : 0, colorful ? 95 : 100);
   283	    }
   284	  }
